export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-12\",\n    \"workId\": \"mo-zi\",\n    \"order\": 12,\n    \"title\": \"尚同中\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 12,\n    \"passageIds\": [\n      \"mo-zi_ch-12_p-1\",\n      \"mo-zi_ch-12_p-2\",\n      \"mo-zi_ch-12_p-3\",\n      \"mo-zi_ch-12_p-4\",\n      \"mo-zi_ch-12_p-5\",\n      \"mo-zi_ch-12_p-6\",\n      \"mo-zi_ch-12_p-7\",\n      \"mo-zi_ch-12_p-8\",\n      \"mo-zi_ch-12_p-9\",\n      \"mo-zi_ch-12_p-10\",\n      \"mo-zi_ch-12_p-11\",\n      \"mo-zi_ch-12_p-12\",\n      \"mo-zi_ch-12_p-13\",\n      \"mo-zi_ch-12_p-14\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-12_p-1\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子曰：「方今之時，復古之民始生，未有正長之時，蓋其語曰『天下之人異義』。是以一人一義，十人十義，百人百義，其人數茲眾，其所謂義者亦茲眾。是以人是其義，而非人之義，故交相非也。內之父子兄弟作怨讎，皆有離散之心，不能相和合。至乎舍餘力不以相勞，隱匿良道不以相教，腐臭餘財不以相分，天下之亂也，至如禽獸然，無君臣上下長幼之節，父子兄弟之禮，是以天下亂焉。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-1_s-1\",\n        \"mo-zi_ch-12_p-1_s-2\",\n        \"mo-zi_ch-12_p-1_s-3\",\n        \"mo-zi_ch-12_p-1_s-4\",\n        \"mo-zi_ch-12_p-1_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"墨子先生親自教導說道：方今的時，復古的民始生，未有正長的時，蓋他的語說道：天下的人異義。是以一人一義，十人十義，百人百義，他的人數茲眾，他的所謂義的人亦茲眾。是以人是他的義，而且絕不是人的義，所以交相絕不是啊。內的父子兄弟作怨讎，皆有離散的心，不能相和合。至乎舍餘力不以相勞，隱匿良道不以相教，腐臭餘財不以相分，天下的亂啊，至如禽獸然，無君臣上下長幼的節，父子兄弟的禮，是以天下亂焉。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「子墨子曰：「方今之時，復古之民始生，未有正長之時，蓋其語曰『天下之人異義』」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「方」、「今」、「時」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「子墨子曰方今之時復古之民始生未有正長之時蓋其語曰」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是以一人一義，十人十義，百人百義，其人數茲眾，其所謂義者亦茲眾」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 2,\n      \"canonicalText\": \"明乎民之無正長以一同天下之義，而天下亂也。是故選擇天下賢良聖知辯慧之人，立以為天子，使從事乎一同天下之義。天子既以立矣，以為唯其耳目之請，不能獨一同天下之義，是故選擇天下贊閱賢良聖知辯慧之人，置以為三公，與從事乎一同天下之義。天子三公既已立矣，以為天下博大，山林遠土之民，不可得而一也，是故靡分天下，設以為萬諸侯國君，使從事乎一同其國之義。國君既已立矣，又以為唯其耳目之請，不能一同其國之義，是故擇其國之賢者，置以為左右將軍大夫，以遠至乎鄉里之長與從事乎一同其國之義。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-2_s-1\",\n        \"mo-zi_ch-12_p-2_s-2\",\n        \"mo-zi_ch-12_p-2_s-3\",\n        \"mo-zi_ch-12_p-2_s-4\",\n        \"mo-zi_ch-12_p-2_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"明乎民的無正長以一同天下的義，而且天下亂啊。正因為如此選擇天下賢良聖知辯慧的人，立以為天子，使從事乎一同天下的義。天子既以立矣，以為唯他的耳目的請，不能獨一同天下的義，正因為如此選擇天下贊閱賢良聖知辯慧的人，置以為三公，與從事乎一同天下的義。天子三公既已立矣，以為天下博大，山林遠土的民，不可得而且一啊，正因為如此靡分天下，設以為萬諸侯國君，使從事乎一同他的國的義。國君既已立矣，又以為唯他的耳目的請，不能一同他的國的義，正因為如此擇他的國的賢的人，置以為左右將軍大夫，以遠至乎鄉里的長與從事乎一同他的國的義。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「明乎民之無正長以一同天下之義，而天下亂也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「明」、「民」、「無」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「明乎民之無正長以一同天下之義而天下亂也是故選擇天」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是故選擇天下賢良聖知辯慧之人，立以為天子，使從事乎一同天下之義」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 3,\n      \"canonicalText\": \"天子諸侯之君，民之正長，既已定矣，天子為發政施教曰：『凡聞見善者，必以告其上，聞見不善者，亦必以告其上。上之所是，必亦是之，上之所非，必亦非之，已有善傍薦之，上有過規諫之。尚同義其上，而毋有下比之心，上得則賞之，萬民聞則譽之。意若聞見善，不以告其上，聞見不善，亦不以告其上，上之所是不能是，上之所非不能非，己有善不能傍薦之，上有過不能規諫之，下比而非其上者，上得則誅罰之，萬民聞則非毀之』。故古者聖王之為刑政賞譽也，甚明察以審信。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-3_s-1\",\n        \"mo-zi_ch-12_p-3_s-2\",\n        \"mo-zi_ch-12_p-3_s-3\",\n        \"mo-zi_ch-12_p-3_s-4\",\n        \"mo-zi_ch-12_p-3_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"天子諸侯的君，民的正長，既已定矣，天子為發政施教說道：凡聞見善的人，必以告他的上，聞見不善的人，亦必以告他的上。上的所是，必亦是的，上的所絕不是，必亦絕不是的，已有善傍薦的，上有過規諫的。上下一心一統政令義他的上，而且毋有下比的心，上得則賞的，萬民聞則譽的。意若聞見善，不以告他的上，聞見不善，亦不以告他的上，上的所是不能是，上的所絕不是不能絕不是，己有善不能傍薦的，上有過不能規諫的，下比而且絕不是他的上的人，上得則誅罰的，萬民聞則絕不是毀的。所以古代聖王的為刑政賞譽啊，甚明察以審信。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「天子諸侯之君，民之正長，既已定矣，天子為發政施教曰：『凡聞見善者，必以告其上，聞見不善者，亦必以告其上」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「天」、「諸」、「侯」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「天子諸侯之君民之正長既已定矣天子為發政施教曰凡聞」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「上之所是，必亦是之，上之所非，必亦非之，已有善傍薦之，上有過規諫之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 4,\n      \"canonicalText\": \"是以舉天下之人，皆欲得上之賞譽，而畏上之毀罰。是故里長順天子政，而一同其裏之義。裏長既同其裏之義，率其裏之萬民，以尚同乎鄉長，曰：『凡裏之萬民，皆尚同乎鄉長，而不敢下比。鄉長之所是，必亦是之，鄉長之所非，必亦非之。去而不善言，學鄉長之善言；去而不善行，學鄉長之善行。鄉長固鄉之賢者也，舉鄉人以法鄉長，夫鄉何說而不治哉？』察鄉長之所以治鄉者何故之以也？曰唯以其能一同其鄉之義，是以鄉治。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-4_s-1\",\n        \"mo-zi_ch-12_p-4_s-2\",\n        \"mo-zi_ch-12_p-4_s-3\",\n        \"mo-zi_ch-12_p-4_s-4\",\n        \"mo-zi_ch-12_p-4_s-5\",\n        \"mo-zi_ch-12_p-4_s-6\",\n        \"mo-zi_ch-12_p-4_s-7\",\n        \"mo-zi_ch-12_p-4_s-8\",\n        \"mo-zi_ch-12_p-4_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"是以舉天下的人，皆欲得上的賞譽，而且畏上的毀罰。正因為如此裏長順天子政，而且一同他的裏的義。裏長既同他的裏的義，率他的裏的萬民，以上下一心一統政令乎鄉長，說道：凡裏的萬民，皆上下一心一統政令乎鄉長，而且不敢下比。鄉長的所是，必亦是的，鄉長的所絕不是，必亦絕不是的。去而且不善言，學鄉長的善言；去而且不善行，學鄉長的善行。鄉長固鄉的賢的人啊，舉鄉人以法鄉長，夫鄉何推理說理而且不治哉？察鄉長的所以治鄉的人何所以的以啊？說道：唯以他的能一同他的鄉的義，是以鄉治。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「是以舉天下之人，皆欲得上之賞譽，而畏上之毀罰」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「舉」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是以舉天下之人皆欲得上之賞譽而畏上之毀罰是故里長」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是故里長順天子政，而一同其裏之義」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 5,\n      \"canonicalText\": \"鄉長治其鄉，而鄉既已治矣，有率其鄉萬民，以尚同乎國君，曰：『凡鄉之萬民，皆上同乎國君，而不敢下比。國君之所是，必亦是之，國君之所非，必亦非之。去而不善言，學國君之善言；去而不善行，學國君之善行。國君固國之賢者也，舉國人以法國君，夫國何說而不治哉？』察國君之所以治國，而國治者，何故之以也？曰唯以其能一同其國之義，是以國治。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-5_s-1\",\n        \"mo-zi_ch-12_p-5_s-2\",\n        \"mo-zi_ch-12_p-5_s-3\",\n        \"mo-zi_ch-12_p-5_s-4\",\n        \"mo-zi_ch-12_p-5_s-5\",\n        \"mo-zi_ch-12_p-5_s-6\",\n        \"mo-zi_ch-12_p-5_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"鄉長治他的鄉，而且鄉既已治矣，有率他的鄉萬民，以上下一心一統政令乎國君，說道：凡鄉的萬民，皆上同乎國君，而且不敢下比。國君的所是，必亦是的，國君的所絕不是，必亦絕不是的。去而且不善言，學國君的善言；去而且不善行，學國君的善行。國君固國的賢的人啊，舉國人以法國君，夫國何推理說理而且不治哉？察國君的所以治國，而且國治的人，何所以的以啊？說道：唯以他的能一同他的國的義，是以國治。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「鄉長治其鄉，而鄉既已治矣，有率其鄉萬民，以尚同乎國君，曰：『凡鄉之萬民，皆上同乎國君，而不敢下比」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「鄉」、「長」、「治」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「鄉長治其鄉而鄉既已治矣有率其鄉萬民以尚同乎國君曰」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「國君之所是，必亦是之，國君之所非，必亦非之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 6,\n      \"canonicalText\": \"國君治其國，而國既已治矣，有率其國之萬民，以尚同乎天子，曰：『凡國之萬民上同乎天子，而不敢下比。天子之所是，必亦是之，天子之所非，必亦非之。去而不善言，學天子之善言；去而不善行，學天子之善行。天子者，固天下之仁人也，舉天下之萬民以法天子，夫天下何說而不治哉？』察天子之所以治天下者，何故之以也？曰唯以其能一同天下之義，是以天下治。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-6_s-1\",\n        \"mo-zi_ch-12_p-6_s-2\",\n        \"mo-zi_ch-12_p-6_s-3\",\n        \"mo-zi_ch-12_p-6_s-4\",\n        \"mo-zi_ch-12_p-6_s-5\",\n        \"mo-zi_ch-12_p-6_s-6\",\n        \"mo-zi_ch-12_p-6_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"國君治他的國，而且國既已治矣，有率他的國的萬民，以上下一心一統政令乎天子，說道：凡國的萬民上同乎天子，而且不敢下比。天子的所是，必亦是的，天子的所絕不是，必亦絕不是的。去而且不善言，學天子的善言；去而且不善行，學天子的善行。天子的人，固天下的仁人啊，舉天下的萬民以法天子，夫天下何推理說理而且不治哉？察天子的所以治天下的人，何所以的以啊？說道：唯以他的能一同天下的義，是以天下治。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「國君治其國，而國既已治矣，有率其國之萬民，以尚同乎天子，曰：『凡國之萬民上同乎天子，而不敢下比」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「國」、「君」、「治」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「國君治其國而國既已治矣有率其國之萬民以尚同乎天子」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「天子之所是，必亦是之，天子之所非，必亦非之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 7,\n      \"canonicalText\": \"夫既尚同乎天子，而未上同乎天者，則天菑將猶未止也。故當若天降寒熱不節，雪霜雨露不時，五穀不孰，六畜不遂，疾菑戾疫、飄風苦雨，荐臻而至者，此天之降罰也，將以罰下人之不尚同乎天者也。故古者聖王，明天鬼之所欲，而避天鬼之所憎，以求興天下之利，除天下之害。是以率天下之萬民，齊戒沐浴，潔為酒醴粢盛，以祭祀天鬼。其事鬼神也，酒醴粢盛不敢不蠲潔，犧牲不敢不腯肥，珪璧幣帛不敢不中度量，春秋祭祀不敢失時幾，聽獄不敢不中，分財不敢不均，居處不敢怠慢。曰其為正長若此，是故上者天鬼有厚乎其為政長也，下者萬民有便利乎其為政長也。天鬼之所深厚而彊從事焉，則天鬼之福可得也。萬民之所便利而能彊從事焉，則萬民之親可得也。其為政若此，是以謀事得，舉事成，入守固，出誅勝者，何故之以也？曰唯以尚同為政者也。故古者聖王之為政若此。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-7_s-1\",\n        \"mo-zi_ch-12_p-7_s-2\",\n        \"mo-zi_ch-12_p-7_s-3\",\n        \"mo-zi_ch-12_p-7_s-4\",\n        \"mo-zi_ch-12_p-7_s-5\",\n        \"mo-zi_ch-12_p-7_s-6\",\n        \"mo-zi_ch-12_p-7_s-7\",\n        \"mo-zi_ch-12_p-7_s-8\",\n        \"mo-zi_ch-12_p-7_s-9\",\n        \"mo-zi_ch-12_p-7_s-10\",\n        \"mo-zi_ch-12_p-7_s-11\",\n        \"mo-zi_ch-12_p-7_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫既上下一心一統政令乎天子，而且未上同乎天的人，則天菑將猶未止啊。所以當若天降寒熱不節，雪霜雨露不時，五穀不孰，六畜不遂，疾菑戾疫、飄風苦雨，荐臻而且至的人，此天的降罰啊，將以罰下人的不上下一心一統政令乎天的人啊。所以古代聖王，明天鬼的所欲，而且避天鬼的所憎，以求興天下的利，除天下的害。是以率天下的萬民，齊戒沐浴，潔為酒醴粢盛，以祭祀天鬼。他的事鬼神啊，酒醴粢盛不敢不蠲潔，犧牲不敢不腯肥，珪璧幣帛不敢不中度量，春秋祭祀不敢失時幾，聽獄不敢不中，分財不敢不均，居處不敢怠慢。說道：他的為正長若此，正因為如此上的人天鬼有厚乎他的為政長啊，下的人萬民有便利乎他的為政長啊。天鬼的所深厚而且彊從事焉，則天鬼的福可得啊。萬民的所便利而且能彊從事焉，則萬民的親可得啊。他的為政若此，是以謀事得，舉事成，入守固，出誅勝的人，何所以的以啊？說道：唯以上下一心一統政令為政的人啊。所以古代聖王的為政若此。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「夫既尚同乎天子，而未上同乎天者，則天菑將猶未止也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「既」、「尚」、「同」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「夫既尚同乎天子而未上同乎天者則天菑將猶未止也故當」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「故當若天降寒熱不節，雪霜雨露不時，五穀不孰，六畜不遂，疾菑戾疫、飄風苦雨，荐臻而至者，此天之降罰也，將以罰下人之不尚同乎天者也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-8\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 8,\n      \"canonicalText\": \"今天下之人曰：「方今之時，天下之正長猶未廢乎天下也，而天下之所以亂者，何故之以也？」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-8_s-1\",\n        \"mo-zi_ch-12_p-8_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今天下的人說道：方今的時，天下的正長猶未廢乎天下啊，而且天下的所以亂的人，何所以的以啊？\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「今天下之人曰：「方今之時，天下之正長猶未廢乎天下也，而天下之所以亂者，何故之以也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「天」、「下」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今天下之人曰方今之時天下之正長猶未廢乎天下也而天」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「今天下之人曰：「方今之時，天下之正長猶未廢乎天下也，而天下之所以亂者，何故之以也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-9\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 9,\n      \"canonicalText\": \"故古者之置正長也，將以治民也，譬之若絲縷之有紀，而罔罟之有綱也，將以運役天下淫暴，而一同其義也。是以先王之書，《相年》之道曰：「夫建國設都，乃作后王君公，否用泰也，輕大夫師長，否用佚也，維辯使治天均。」則此語古者上帝鬼神之建設國都，立正長也，非高其爵，厚其祿，富貴佚而錯之也，將以為萬民興利除害，富貴貧寡，安危治亂也。故古者聖王之為若此。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-9_s-1\",\n        \"mo-zi_ch-12_p-9_s-2\",\n        \"mo-zi_ch-12_p-9_s-3\",\n        \"mo-zi_ch-12_p-9_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以古代的置正長啊，將以治民啊，譬的若絲縷的有紀，而且罔罟的有綱啊，將以運役天下淫暴，而且一同他的義啊。是以先王的書，《相年》的道說道：夫建國設都，乃作后王君公，否用泰啊，輕大夫師長，否用佚啊，維辯使治天均。則此語古代上帝鬼神的建設國都，立正長啊，絕不是高他的爵，厚他的祿，富貴佚而且錯的啊，將以為萬民興利除害，富貴貧寡，安危治亂啊。所以古代聖王的為若此。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「故古者之置正長也，將以治民也，譬之若絲縷之有紀，而罔罟之有綱也，將以運役天下淫暴，而一同其義也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「古」、「置」、「正」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故古者之置正長也將以治民也譬之若絲縷之有紀而罔罟」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是以先王之書，《相年》之道曰：「夫建國設都，乃作后王君公，否用泰也，輕大夫師長，否用佚也，維辯使治天均」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 10,\n      \"canonicalText\": \"今王公大人之為刑政則反此。政以為便譬，宗於父兄故舊，以為左右，置以為正長。民知上置正長之非正以治民也，是以皆比周隱匿，而莫肯尚同其上。是故上下不同義。若苟上下不同義，賞譽不足以勸善，而刑罰不足以沮暴。何以知其然也？\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-10_s-1\",\n        \"mo-zi_ch-12_p-10_s-2\",\n        \"mo-zi_ch-12_p-10_s-3\",\n        \"mo-zi_ch-12_p-10_s-4\",\n        \"mo-zi_ch-12_p-10_s-5\",\n        \"mo-zi_ch-12_p-10_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今王公大人的為刑政則反此。政以為便譬，宗於父兄所以舊，以為左右，置以為正長。民知上置正長的絕不是正以治民啊，是以皆比周隱匿，而且莫肯上下一心一統政令他的上。正因為如此上下不同義。若苟上下不同義，賞譽不足以勸善，而且刑罰不足以沮暴。何以知他的然啊？\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「今王公大人之為刑政則反此」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「今」、「王」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「今王公大人之為刑政則反此政以為便譬宗於父兄故舊以」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「政以為便譬，宗於父兄故舊，以為左右，置以為正長」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 11,\n      \"canonicalText\": \"曰：上唯毋立而為政乎國家，為民正長，曰：「人可賞吾，將賞之。」若苟上下不同義，上之所賞，則眾之所非，曰人眾與處，於眾得非。則是雖使得上之賞，未足以勸乎！上唯毋立而為政乎國家，為民正長，曰：「人可罰，吾將罰之。」若苟上下不同義，上之所罰，則眾之所譽。曰人眾與處，於眾得譽，則是雖使得上之罰，未足以沮乎！若立而為政乎國家，為民正長，賞譽不足以勸善，而刑罰不可以沮暴，則是不與鄉吾本言「民始生未有正長之時」同乎！若有正長與無正長之時同，則此非所以治民一眾之道。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-11_s-1\",\n        \"mo-zi_ch-12_p-11_s-2\",\n        \"mo-zi_ch-12_p-11_s-3\",\n        \"mo-zi_ch-12_p-11_s-4\",\n        \"mo-zi_ch-12_p-11_s-5\",\n        \"mo-zi_ch-12_p-11_s-6\",\n        \"mo-zi_ch-12_p-11_s-7\",\n        \"mo-zi_ch-12_p-11_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"說道：上唯毋立而且為政乎國家，為民正長，說道：人可賞吾，將賞的。若苟上下不同義，上的所賞，則眾的所絕不是，說道：人眾與處，於眾得絕不是。則是雖使得上的賞，未足以勸乎！上唯毋立而且為政乎國家，為民正長，說道：人可罰，吾將罰的。若苟上下不同義，上的所罰，則眾的所譽。說道：人眾與處，於眾得譽，則是雖使得上的罰，未足以沮乎！若立而且為政乎國家，為民正長，賞譽不足以勸善，而且刑罰不可以沮暴，則是不與鄉吾本言民始生未有正長的時同乎！若有正長與無正長的時同，則此絕不是所以治民一眾的道。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「曰：上唯毋立而為政乎國家，為民正長，曰：「人可賞吾，將賞之」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「上」、「唯」、「毋」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「曰上唯毋立而為政乎國家為民正長曰人可賞吾將賞之若」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」若苟上下不同義，上之所賞，則眾之所非，曰人眾與處，於眾得非」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 12,\n      \"canonicalText\": \"故古者聖王唯而審以尚同，以為正長，是故上下情請為通。上有隱事遺利，下得而利之；下有蓄怨積害，上得而除之。是以數千萬裏之外，有為善者，其室人未遍知，鄉里未遍聞，天子得而賞之。數千萬裏之外，有為不善者，其室人未遍知，鄉里未遍聞，天子得而罰之。是以舉天下之人皆恐懼振動惕慄，不敢為淫暴，曰：「天子之視聽也神。」先王之言曰：「非神也，夫唯能使人之耳目助己視聽，使人之吻助己言談，使人之心助己思慮，使人之股肱助己動作」。助之視聽者眾，則其所聞見者遠矣；助之言談者眾，則其德音之所撫循者博矣；助之思慮者眾，則其談謀度速得矣；助之動作者眾，即其舉事速成矣。故古者聖人之所以濟事成功，垂名於後世者，無他故異物焉，曰唯能以尚同為政者也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-12_s-1\",\n        \"mo-zi_ch-12_p-12_s-2\",\n        \"mo-zi_ch-12_p-12_s-3\",\n        \"mo-zi_ch-12_p-12_s-4\",\n        \"mo-zi_ch-12_p-12_s-5\",\n        \"mo-zi_ch-12_p-12_s-6\",\n        \"mo-zi_ch-12_p-12_s-7\",\n        \"mo-zi_ch-12_p-12_s-8\",\n        \"mo-zi_ch-12_p-12_s-9\",\n        \"mo-zi_ch-12_p-12_s-10\",\n        \"mo-zi_ch-12_p-12_s-11\",\n        \"mo-zi_ch-12_p-12_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以古代聖王唯而且審以上下一心一統政令，以為正長，正因為如此上下情請為通。上有隱事遺利，下得而且利的；下有蓄怨積害，上得而且除的。是以數千萬裏的外，有為善的人，他的室人未遍知，鄉里未遍聞，天子得而且賞的。數千萬裏的外，有為不善的人，他的室人未遍知，鄉里未遍聞，天子得而且罰的。是以舉天下的人皆恐懼振動惕慄，不敢為淫暴，說道：天子的視聽啊神。先王的說道：絕不是神啊，夫唯能使人的耳目助己視聽，使人的吻助己言談，使人的心助己思慮，使人的股肱助己動作。助的視聽的人眾，則他的所聞見的人遠矣；助的言談的人眾，則他的德音的所撫循的人博矣；助的思慮的人眾，則他的談謀度速得矣；助的動作的人眾，即他的舉事速成矣。所以古代聖人的所以濟事成功，垂概念名詞於後世的人，無他所以異物焉，說道：唯能以上下一心一統政令為政的人啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「故古者聖王唯而審以尚同，以為正長，是故上下情請為通」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「古」、「聖」、「王」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「故古者聖王唯而審以尚同以為正長是故上下情請為通上」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「上有隱事遺利，下得而利之」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 13,\n      \"canonicalText\": \"是以先王之書《周頌》之道之曰：「載來見彼王，聿求厥章。」則此語古者國君諸侯之以春秋來朝聘天子之廷，受天子之嚴教，退而治國，政之所加，莫敢不賓。當此之時，本無有敢紛天子之教者。《詩》曰：「我馬維駱，六轡沃若，載馳載驅，周爰諮度。」又曰：「我馬維騏，六轡若絲，載馳載驅，周爰諮謀。」即此語也。古者國君諸侯之聞見善與不善也，皆馳驅以告天子，是以賞當賢，罰當暴，不殺不辜，不失有罪，則此尚同之功也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-13_s-1\",\n        \"mo-zi_ch-12_p-13_s-2\",\n        \"mo-zi_ch-12_p-13_s-3\",\n        \"mo-zi_ch-12_p-13_s-4\",\n        \"mo-zi_ch-12_p-13_s-5\",\n        \"mo-zi_ch-12_p-13_s-6\",\n        \"mo-zi_ch-12_p-13_s-7\",\n        \"mo-zi_ch-12_p-13_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"是以先王的書《周頌》的道說道：載來見彼王，聿求厥章。則此語古代國君諸侯的以春秋來朝聘天子的廷，受天子的嚴教，退而且治國，政的所加，莫敢不賓。當此的時，本無有敢紛天子的教的人。《詩》說道：我馬維駱，六轡沃若，載馳載驅，周爰諮度。又說道：我馬維騏，六轡若絲，載馳載驅，周爰諮謀。即此語啊。古代國君諸侯的聞見善與不善啊，皆馳驅以告天子，是以賞當賢，罰當暴，不殺不辜，不失有罪，則此上下一心一統政令的功啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「是以先王之書《周頌》之道之曰：「載來見彼王，聿求厥章」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「先」、「王」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是以先王之書周頌之道之曰載來見彼王聿求厥章則此語」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」則此語古者國君諸侯之以春秋來朝聘天子之廷，受天子之嚴教，退而治國，政之所加，莫敢不賓」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-14\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"order\": 14,\n      \"canonicalText\": \"是故子墨子曰：「今天下之王公大人士君子，請將欲富其國家，眾其人民，治其刑政，定其社稷，當若尚同之不可不察，此之本也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-12_p-14_s-1\",\n        \"mo-zi_ch-12_p-14_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"正因為如此墨子先生親自教導說道：今天下的王公大人士君子，請將欲富他的國家，眾他的人民，治他的刑政，定他的社稷，當若上下一心一統政令的不可不察，此的本啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈尚同中〉。墨子學派以兼愛天下為宗，開篇「是故子墨子曰：「今天下之王公大人士君子，請將欲富其國家，眾其人民，治其刑政，定其社稷，當若尚同之不可不察，此之本也」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「是」、「今」、「天」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「是故子墨子曰今天下之王公大人士君子請將欲富其國家」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是故子墨子曰：「今天下之王公大人士君子，請將欲富其國家，眾其人民，治其刑政，定其社稷，當若尚同之不可不察，此之本也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-12_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"子墨子曰：「方今之時，復古之民始生，未有正長之時，蓋其語曰『天下之人異義』。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"是以一人一義，十人十義，百人百義，其人數茲眾，其所謂義者亦茲眾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"是以人是其義，而非人之義，故交相非也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"內之父子兄弟作怨讎，皆有離散之心，不能相和合。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"至乎舍餘力不以相勞，隱匿良道不以相教，腐臭餘財不以相分，天下之亂也，至如禽獸然，無君臣上下長幼之節，父子兄弟之禮，是以天下亂焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"明乎民之無正長以一同天下之義，而天下亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"是故選擇天下賢良聖知辯慧之人，立以為天子，使從事乎一同天下之義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"天子既以立矣，以為唯其耳目之請，不能獨一同天下之義，是故選擇天下贊閱賢良聖知辯慧之人，置以為三公，與從事乎一同天下之義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"天子三公既已立矣，以為天下博大，山林遠土之民，不可得而一也，是故靡分天下，設以為萬諸侯國君，使從事乎一同其國之義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"國君既已立矣，又以為唯其耳目之請，不能一同其國之義，是故擇其國之賢者，置以為左右將軍大夫，以遠至乎鄉里之長與從事乎一同其國之義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"天子諸侯之君，民之正長，既已定矣，天子為發政施教曰：『凡聞見善者，必以告其上，聞見不善者，亦必以告其上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"上之所是，必亦是之，上之所非，必亦非之，已有善傍薦之，上有過規諫之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"尚同義其上，而毋有下比之心，上得則賞之，萬民聞則譽之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"意若聞見善，不以告其上，聞見不善，亦不以告其上，上之所是不能是，上之所非不能非，己有善不能傍薦之，上有過不能規諫之，下比而非其上者，上得則誅罰之，萬民聞則非毀之』。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"故古者聖王之為刑政賞譽也，甚明察以審信。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"是以舉天下之人，皆欲得上之賞譽，而畏上之毀罰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"是故里長順天子政，而一同其裏之義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"裏長既同其裏之義，率其裏之萬民，以尚同乎鄉長，曰：『凡裏之萬民，皆尚同乎鄉長，而不敢下比。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"鄉長之所是，必亦是之，鄉長之所非，必亦非之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"去而不善言，學鄉長之善言；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"去而不善行，學鄉長之善行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"鄉長固鄉之賢者也，舉鄉人以法鄉長，夫鄉何說而不治哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"』察鄉長之所以治鄉者何故之以也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-4_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"曰唯以其能一同其鄉之義，是以鄉治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"鄉長治其鄉，而鄉既已治矣，有率其鄉萬民，以尚同乎國君，曰：『凡鄉之萬民，皆上同乎國君，而不敢下比。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"國君之所是，必亦是之，國君之所非，必亦非之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"去而不善言，學國君之善言；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"去而不善行，學國君之善行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"國君固國之賢者也，舉國人以法國君，夫國何說而不治哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"』察國君之所以治國，而國治者，何故之以也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-5_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"曰唯以其能一同其國之義，是以國治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"國君治其國，而國既已治矣，有率其國之萬民，以尚同乎天子，曰：『凡國之萬民上同乎天子，而不敢下比。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"天子之所是，必亦是之，天子之所非，必亦非之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"去而不善言，學天子之善言；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"去而不善行，學天子之善行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"天子者，固天下之仁人也，舉天下之萬民以法天子，夫天下何說而不治哉？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"』察天子之所以治天下者，何故之以也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"曰唯以其能一同天下之義，是以天下治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"夫既尚同乎天子，而未上同乎天者，則天菑將猶未止也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"故當若天降寒熱不節，雪霜雨露不時，五穀不孰，六畜不遂，疾菑戾疫、飄風苦雨，荐臻而至者，此天之降罰也，將以罰下人之不尚同乎天者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"故古者聖王，明天鬼之所欲，而避天鬼之所憎，以求興天下之利，除天下之害。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"是以率天下之萬民，齊戒沐浴，潔為酒醴粢盛，以祭祀天鬼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"其事鬼神也，酒醴粢盛不敢不蠲潔，犧牲不敢不腯肥，珪璧幣帛不敢不中度量，春秋祭祀不敢失時幾，聽獄不敢不中，分財不敢不均，居處不敢怠慢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"曰其為正長若此，是故上者天鬼有厚乎其為政長也，下者萬民有便利乎其為政長也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"天鬼之所深厚而彊從事焉，則天鬼之福可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"萬民之所便利而能彊從事焉，則萬民之親可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"其為政若此，是以謀事得，舉事成，入守固，出誅勝者，何故之以也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"曰唯以尚同為政者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 11,\n      \"canonicalText\": \"故古者聖王之為政若此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-7_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-7\",\n      \"order\": 12,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"今天下之人曰：「方今之時，天下之正長猶未廢乎天下也，而天下之所以亂者，何故之以也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-9_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"故古者之置正長也，將以治民也，譬之若絲縷之有紀，而罔罟之有綱也，將以運役天下淫暴，而一同其義也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-9_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"是以先王之書，《相年》之道曰：「夫建國設都，乃作后王君公，否用泰也，輕大夫師長，否用佚也，維辯使治天均。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-9_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"」則此語古者上帝鬼神之建設國都，立正長也，非高其爵，厚其祿，富貴佚而錯之也，將以為萬民興利除害，富貴貧寡，安危治亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-9_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"故古者聖王之為若此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"今王公大人之為刑政則反此。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"政以為便譬，宗於父兄故舊，以為左右，置以為正長。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"民知上置正長之非正以治民也，是以皆比周隱匿，而莫肯尚同其上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"是故上下不同義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"若苟上下不同義，賞譽不足以勸善，而刑罰不足以沮暴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-10_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"何以知其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"曰：上唯毋立而為政乎國家，為民正長，曰：「人可賞吾，將賞之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"」若苟上下不同義，上之所賞，則眾之所非，曰人眾與處，於眾得非。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"則是雖使得上之賞，未足以勸乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"上唯毋立而為政乎國家，為民正長，曰：「人可罰，吾將罰之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"」若苟上下不同義，上之所罰，則眾之所譽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"曰人眾與處，於眾得譽，則是雖使得上之罰，未足以沮乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"若立而為政乎國家，為民正長，賞譽不足以勸善，而刑罰不可以沮暴，則是不與鄉吾本言「民始生未有正長之時」同乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-11_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"若有正長與無正長之時同，則此非所以治民一眾之道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"故古者聖王唯而審以尚同，以為正長，是故上下情請為通。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"上有隱事遺利，下得而利之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"下有蓄怨積害，上得而除之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"是以數千萬裏之外，有為善者，其室人未遍知，鄉里未遍聞，天子得而賞之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"數千萬裏之外，有為不善者，其室人未遍知，鄉里未遍聞，天子得而罰之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"是以舉天下之人皆恐懼振動惕慄，不敢為淫暴，曰：「天子之視聽也神。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"」先王之言曰：「非神也，夫唯能使人之耳目助己視聽，使人之吻助己言談，使人之心助己思慮，使人之股肱助己動作」。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"助之視聽者眾，則其所聞見者遠矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"助之言談者眾，則其德音之所撫循者博矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"助之思慮者眾，則其談謀度速得矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"助之動作者眾，即其舉事速成矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-12_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"故古者聖人之所以濟事成功，垂名於後世者，無他故異物焉，曰唯能以尚同為政者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"是以先王之書《周頌》之道之曰：「載來見彼王，聿求厥章。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"」則此語古者國君諸侯之以春秋來朝聘天子之廷，受天子之嚴教，退而治國，政之所加，莫敢不賓。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"當此之時，本無有敢紛天子之教者。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"《詩》曰：「我馬維駱，六轡沃若，載馳載驅，周爰諮度。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"」又曰：「我馬維騏，六轡若絲，載馳載驅，周爰諮謀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"」即此語也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"古者國君諸侯之聞見善與不善也，皆馳驅以告天子，是以賞當賢，罰當暴，不殺不辜，不失有罪，則此尚同之功也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-13_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-14_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"是故子墨子曰：「今天下之王公大人士君子，請將欲富其國家，眾其人民，治其刑政，定其社稷，當若尚同之不可不察，此之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-12_p-14_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-12\",\n      \"passageId\": \"mo-zi_ch-12_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
